  String task=(String)candidate.get("task_id");var before=j.queryForMap("SELECT * FROM generation_candidate WHERE id=?",candidate.get("id"));var row=j.queryForMap("SELECT o.*,e.id execution_id FROM external_operation o JOIN external_execution e ON e.operation_id=o.id AND e.execution_no=o.current_execution_no WHERE e.task_id=?",task);var token=new OperationToken((String)row.get("id"),(String)row.get("execution_id"),((Number)row.get("current_execution_no")).longValue(),((Number)row.get("reconcile_epoch")).longValue(),(String)row.get("reconcile_owner"),((java.time.LocalDateTime)row.get("reconcile_expires_at")).toInstant(java.time.ZoneOffset.UTC),new SubjectRef("MEETING",meeting));assertNull(j.queryForObject("SELECT lease_owner FROM durable_task WHERE id=?",String.class,task));var request=preparation.prepareLookup(token);var wire=client.prepare(request.body(token.executionId()),request.envelope());var receipt=client.lookup(wire,NEVER);assertEquals(row.get("external_result_id"),receipt.resultId());var observation=preparation.accept(request,token,wire,receipt,NEVER);assertEquals(ObservationResult.RECORDED_FENCED,operations.recoverPreparedFact(token,observation));assertEquals(before,j.queryForMap("SELECT * FROM generation_candidate WHERE id=?",candidate.get("id")));assertEquals(1,j.queryForObject("SELECT COUNT(*) FROM generation_candidate WHERE task_id=?",Integer.class,task));assertEquals(1,j.queryForObject("SELECT COUNT(*) FROM external_execution WHERE task_id=?",Integer.class,task));java.nio.file.Files.writeString(this.receipt.resolve("actual-stale-terminal-replay.json"),json.writeValueAsString(Map.of("task",task,"candidate",candidate.get("id"),"resultId",receipt.resultId(),"freshLookup",true,"sameExistingGraph",true,"resend",false)));
